/** 
 * @description when .ts files have no explicit exports, it will not treat the file as a module.
 * standard workaround is to just export an empty object to force the behaviour
 * @link https://github.com/microsoft/TypeScript/issues/18232#issuecomment-326912884
 *  */
export { };

Number.prototype.clamp = function (this: number, min: number = 0, max: number = 1) {
    return Math.clamp(this, min, max);
};

Number.prototype.remapClamp = function (this: number, low: number, high: number, remapLow: number = 0, remapHigh: number = 1) {
    return Math.remapClamp(this, low, high, remapLow, remapHigh);
};

Number.prototype.remap = function (this: number, low: number, high: number, remapLow: number = 0, remapHigh: number = 1): number {
    return Math.remap(this, low, high, remapLow, remapHigh);
};

Number.prototype.smoothStep = function (this: number, clamp: boolean = true) {
    return Math.smoothStep(this, clamp);
};

Number.prototype.smootherStep = function (this: number, clamp: boolean = true) {
    return Math.smootherStep(this, clamp);
};

Number.prototype.hasSomeFlags = function (this: number, ...flags: number[]) {
    // tslint:disable-next-line:no-bitwise
    return flags.some((flag) => flag === (this & flag));
};

Number.prototype.hasAllFlags = function (this: number, ...flags: number[]) {
    // tslint:disable-next-line:no-bitwise
    return !flags.some((flag) => flag !== (this & flag));
};

Number.prototype.roundToNearestMultiple = function (this: number, multiple: number) {
    return Math.roundToNearestMultiple(this, multiple);
};

Number.prototype.interpolate = function (this: number, target: number, t: number): number {
    return Math.interpolate(this, target, t);
};

Number.prototype.interpolateDelta = function (this: number, target: number, t: number, dt: number): number {
    return Math.interpolateDelta(this, target, t, dt);
};

Number.prototype.mod = function (this: number, m: number): number {
    return Math.mod(this, m);
};

declare global {
    // tslint:disable-next-line:interface-name
    interface Number {
        clamp(this: number, min?: number, max?: number): number;
        remapClamp(this: number, low: number, high: number, remapLow?: number, remapHigh?: number): number;
        remap(this: number, low: number, high: number, remapLow?: number, remapHigh?: number): number;
        smoothStep(this: number, clamp: boolean): number;
        smootherStep(this: number, clamp: boolean): number;
        hasSomeFlags(this: number, ...flags: number[]): boolean;
        hasAllFlags(this: number, ...flags: number[]): boolean;
        roundToNearestMultiple(this: number, multiple: number): number;
        interpolate(this: number, target: number, t: number): number;
        interpolateDelta(this: number, target: number, t: number, dt: number): number;
        mod(this: number, m: number): number;
    }
}